-- 016E: Migrate the existing public archive into the editable album directory.
-- No photos are stored or deleted. Existing manually added records are preserved.
begin;
alter table public.toolbox_albums
  drop constraint toolbox_albums_event_month_check,
  add constraint toolbox_albums_event_month_check
    check (event_month ~ '^20[0-9]{2}(-(0[1-9]|1[0-2]))?$'),
  add column updated_at timestamptz not null default now();

-- Seed the 297 public archive links and their validated cover URLs.
insert into public.toolbox_albums(unit_id,album_url,title,event_month,category,cover_url)
select u.id,a.album_url,a.title,a.event_month,a.category,a.cover_url
from public.units u
cross join (values
