create function public.update_toolbox_album(
  p_unit_id uuid,p_album_id uuid,p_expected_updated_at timestamptz,
  p_album_url text,p_title text,p_event_month text,p_category text,p_cover_url text
)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not toolbox_private.has_staff_access(p_unit_id,true) then
    raise exception 'Administrator access required';
  end if;
  perform toolbox_private.lock_family_lifecycle(p_unit_id);
  update public.toolbox_albums
  set album_url=btrim(p_album_url), title=btrim(p_title),
      event_month=nullif(btrim(p_event_month),''), category=p_category,
      cover_url=nullif(btrim(p_cover_url),''), updated_at=clock_timestamp()
  where id=p_album_id and unit_id=p_unit_id and updated_at=p_expected_updated_at;
  if not found then raise exception 'Album changed or unavailable; refresh and try again'; end if;
  insert into public.audit_logs(unit_id,actor_profile_id,action,entity_type,entity_id)
  values(p_unit_id,auth.uid(),'album.updated','album',p_album_id);
end;
$$;

create function public.remove_toolbox_album(
  p_unit_id uuid,p_album_id uuid,p_expected_updated_at timestamptz
)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not toolbox_private.has_staff_access(p_unit_id,true) then
    raise exception 'Administrator access required';
  end if;
  perform toolbox_private.lock_family_lifecycle(p_unit_id);
  delete from public.toolbox_albums
  where id=p_album_id and unit_id=p_unit_id and updated_at=p_expected_updated_at;
  if not found then raise exception 'Album changed or unavailable; refresh and try again'; end if;
  insert into public.audit_logs(unit_id,actor_profile_id,action,entity_type,entity_id)
  values(p_unit_id,auth.uid(),'album.removed','album',p_album_id);
end;
$$;
revoke all on function public.update_toolbox_album(uuid,uuid,timestamptz,text,text,text,text,text) from public,anon,authenticated;
revoke all on function public.remove_toolbox_album(uuid,uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.update_toolbox_album(uuid,uuid,timestamptz,text,text,text,text,text) to authenticated;
grant execute on function public.remove_toolbox_album(uuid,uuid,timestamptz) to authenticated;

do $$
begin
  if (select count(*) from public.toolbox_albums a join public.units u on u.id=a.unit_id where u.slug='troop-120') < 297 then
    raise exception 'Archive import incomplete';
  end if;
end $$;
commit;

select count(*) as total_album_records,
 count(*) filter (where cover_url is not null) as albums_with_cover
from public.toolbox_albums a join public.units u on u.id=a.unit_id
where u.slug='troop-120';
